def findCheapestPrice(n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
    price = [float("inf")] * n
    price[src] = 0
    for _ in range(k + 1):
        nxt = price[:]
        for u, v, w in flights:
            if price[u] + w < nxt[v]: nxt[v] = price[u] + w
        price = nxt
    return -1 if price[dst] == float("inf") else price[dst]

